# Early exit using yield
method check_even(n) {
    when n % 2 == 0 {
        yield True
    }
    yield False
}

show("Is 4 even?", check_even(4))
show("Is 7 even?", check_even(7))

# Returning multiple values
method min_and_max(nums) {
    min_val = nums[0]
    max_val = nums[0]
    trace n <- nums {
        when n < min_val { min_val = n }
        when n > max_val { max_val = n }
    }
    yield min_val, max_val
}

low, high = min_and_max([45, 12, 89, 3, 67])
show("Lowest:", low, "| Highest:", high)

# Implicit Null return
method do_work() {
    show("Performing side effect...")
}
res = do_work()
show("Return of do_work:", res)

