# 1. Passing anonymous function as callback
method apply_operation(func, a, b) {
    yield func(a, b)
}

# Pass inline anonymous functions
sum = apply_operation(method(x, y) { yield x + y }, 20, 10)
product = apply_operation(method(x, y) { yield x * y }, 20, 10)
show("Sum via callback:", sum)
show("Product via callback:", product)

# 2. Lexical Closures (Function Factory)
method create_multiplier(factor) {
    yield method(n) {
        yield n * factor
    }
}

double = create_multiplier(2)
triple = create_multiplier(3)

show("double(15):", double(15))
show("triple(15):", triple(15))
show("double(50):", double(50))

