model Point {
    open attr <x, y>

    init(x = 0, y = 0) {
        x: x,
        y: y
    }

    open method distance_from_origin() {
        yield ((x ** 2) + (y ** 2)) ** 0.5
    }

    open method translate(dx, dy) {
        x += dx
        y += dy
    }

    open method show_point() {
        show($"Point({x}, {y})")
    }
}

# Instantiation
pt = Point(3, 4)
pt.show_point()
show("Distance from origin:", pt.distance_from_origin())

# Mutating instance state
pt.translate(2, -1)
pt.show_point()

model BankAccount {
    open attr <account_holder>
    guarded attr <balance>
    secret attr <pin>

    init(holder, initial_balance, pin_code) {
        account_holder: holder,
        balance: initial_balance,
        pin: pin_code
    }

    open method deposit(amount) {
        when amount > 0 {
            balance += amount
            show($"Deposited ${amount}. New balance: ${balance}")
        }
    }

    open method check_balance(entered_pin) {
        when entered_pin == pin {
            yield balance
        }
        show("Access Denied: Invalid PIN!")
        yield Null
    }
}

acc = BankAccount("Souvik", 1000, 4321)
show("Public holder name:", acc.account_holder)
acc.deposit(250)
show("Verified balance:", acc.check_balance(4321))

