model Animal {
    open attr <name, species>

    init(name, species) {
        name: name,
        species: species
    }

    open method speak() {
        yield "Some generic sound"
    }

    open method describe() {
        show($"{name} is a {species}. It says: {speak()}")
    }
}

model Dog: Animal {
    open attr <breed>

    init(name, breed) {
        name: name,
        species: "Canine",
        breed: breed
    }

    # Override speak()
    open method speak() {
        yield "Woof! Woof!"
    }
}

model Cat: Animal {
    init(name) {
        name: name,
        species: "Feline"
    }

    # Override speak()
    open method speak() {
        yield "Meow!"
    }
}

dog = Dog("Buddy", "Golden Retriever")
cat = Cat("Luna")

dog.describe()
cat.describe()

model Vec2 {
    open attr <x, y>

    init(x, y) {
        x: x,
        y: y
    }

    method __add__(other) {
        yield Vec2(x + other.x, y + other.y)
    }

    method __sub__(other) {
        yield Vec2(x - other.x, y - other.y)
    }

    method __mul__(scalar) {
        yield Vec2(x * scalar, y * scalar)
    }

    method __eq__(other) {
        yield (x == other.x) and (y == other.y)
    }

    method __neg__() {
        yield Vec2(-x, -y)
    }

    method to_str() {
        yield $"Vec2({x}, {y})"
    }
}

v1 = Vec2(10, 20)
v2 = Vec2(5, 15)

# Vector Addition
v3 = v1 + v2
show("v1 + v2 =", v3.to_str())

# Vector Subtraction
v4 = v1 - v2
show("v1 - v2 =", v4.to_str())

# Scalar Multiplication
v5 = v1 * 3
show("v1 * 3 =", v5.to_str())

# Equality check
show("v1 == v2:", v1 == v2)
show("v1 == Vec2(10, 20):", v1 == Vec2(10, 20))

# Negation
v_neg = -v1
show("-v1 =", v_neg.to_str())

