# 1. Specific trap with clean block
risk {
    show("Attempting division by zero...")
    val = 100 / 0
    show("This line will NOT run")
} trap RunTimeError err {
    show("Caught expected exception:")
    show("  Error Details:", err.message)
} clean {
    show("Clean block executed: Resources released.")
}

# 2. Bare trap (catches any error)
show("--- Bare Trap Demonstration ---")
risk {
    items = [1, 2]
    bad_access = items[10]
} trap {
    show("Bare trap caught out-of-bounds error successfully!")
}

method test_error(code) {
    risk {
        when code == 1 {
            x = 10 / 0
        } orwhen code == 2 {
            d = {"a": 1}
            x = d["missing"]
        } otherwise {
            lst = [1]
            x = lst[10]
        }
    } trap DivisionByZeroError e {
        show("Handled DivisionByZeroError:", e.message)
    } trap DictKeyError e {
        show("Handled DictKeyError:", e.message)
    } trap IndexOutOfBoundsError e {
        show("Handled IndexOutOfBoundsError:", e.message)
    }
}

test_error(1)
test_error(2)
test_error(3)

model ValidationError {
    open attr <field, message>

    init(field, message) {
        field: field,
        message: message
    }
}

method validate_age(age) {
    when age < 0 {
        throw(ValidationError("age", "Age cannot be negative"))
    } orwhen age > 150 {
        throw(ValidationError("age", "Age exceeds human limit"))
    }
    show("Age validated:", age)
}

# Catching custom error
risk {
    validate_age(-5)
} trap ValidationError err {
    show("Caught ValidationError:")
    show("  Field:", err.field)
    show("  Message:", err.message)
}

# Recursive method demonstrating call stack boundary enforcement
method recursive_call(depth) {
    when depth > 0 {
        yield recursive_call(depth - 1)
    }
    yield "Base reached"
}

show("--- Safe In-Bounds Recursion ---")
res = recursive_call(10)
show("Recursion result:", res)

# Attempting recursion beyond the 100-frame limit inside a risk block
risk {
    show("Attempting 150 recursive frames...")
    recursive_call(150)
} trap RunTimeError err {
    show("Sandbox caught depth exceeded:")
    show("  Message:", err.message)
}
